class Solution {
  public int maxCapacity(int[] costs, int[] capacity, int budget) {
    int n = costs.length;
    Integer[] order = new Integer[n];
    for (int i = 0; i < n; i++) order[i] = i;
    java.util.Arrays.sort(order, (a, b) -> Integer.compare(costs[a], costs[b]));
    int[] sortedCost = new int[n], prefMax = new int[n];
    for (int i = 0; i < n; i++) {
      sortedCost[i] = costs[order[i]];
      prefMax[i] = Math.max(i > 0 ? prefMax[i - 1] : 0, capacity[order[i]]);
    }
    int best = 0;
    for (int i = 0; i < n; i++) {
      if (sortedCost[i] >= budget) break;
      int cap = capacity[order[i]];
      best = Math.max(best, cap);
      // partners among indices < i with cost < budget - cost_i
      int limit = budget - sortedCost[i], lo = 0, hi = i;
      while (lo < hi) {
        int mid = (lo + hi) >>> 1;
        if (sortedCost[mid] < limit) lo = mid + 1;
        else hi = mid;
      }
      if (lo > 0) best = Math.max(best, cap + prefMax[lo - 1]);
    }
    return best;
  }
}
